INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("2020/04/30 12:00:00", 0, 24001, 0, 10040, "あたしだって\nやるときはやるよ！", "リン", "2030/12/17 14:59:59", 24, 0, 1, 102601, 0, 1);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("2020/04/30 12:00:00", 0, 24002, 1, 10040, "ふぅ…\nこれであたしの仕事は\n終わりだね", "リン", "2030/12/17 14:59:59", 24, 0, 1, 102601, 0, 1);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("2020/04/30 12:00:00", 0, 24003, 2, 10040, "終わった終わった\n一人でもなんとか\nなるもんだね", "リン", "2030/12/17 14:59:59", 24, 0, 1, 102601, 0, 1);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("2020/04/30 12:00:00", 0, 24004, 3, 10040, "やったね！\nこれでようやく\nサボれるよ…", "リン", "2030/12/17 14:59:59", 24, 0, 2, 102601, 0, 2);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("2020/04/30 12:00:00", 0, 24005, 4, 10040, "チーズが欲しいなら\nきちんと働いて\n買いに来なよ", "リン", "2030/12/17 14:59:59", 24, 0, 1, 102601, 0, 1);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("2020/04/30 12:00:00", 0, 24006, 5, 10040, "あたしを敵に回した\n恐ろしさ\n思い知ったか！", "リン", "2030/12/17 14:59:59", 24, 0, 2, 102601, 0, 2);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("2020/04/30 12:00:00", 0, 24007, 6, 10040, "あたしも意外と\nやるもんでしょ？", "リン", "2030/12/17 14:59:59", 24, 0, 2, 102601, 0, 2);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("2020/04/30 12:00:00", 0, 24008, 7, 10040, "疲れた…\nねずみの逃げ足\n速すぎるよ…", "リン", "2030/12/17 14:59:59", 24, 0, 4, 102601, 0, 4);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("2020/04/30 12:00:00", 0, 24009, 8, 10040, "このままじゃ\nまっひ～に\n叱られちゃうよ", "リン", "2030/12/17 14:59:59", 24, 0, 4, 102601, 0, 4);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("2020/04/30 12:00:00", 0, 24010, 9, 10040, "まじめに\nやったんだけどな…\n悔しいな～", "リン", "2030/12/17 14:59:59", 24, 0, 4, 102601, 0, 4);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("2020/04/30 12:00:00", 0, 24011, 10, 10040, "やられた…\nねずみって意外と\nてごわいね", "リン", "2030/12/17 14:59:59", 24, 0, 4, 102601, 0, 4);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("2020/04/30 12:00:00", 0, 24012, 11, 10040, "おのれ～\nあたしのチーズを\n盗みやがって～！", "リン", "2030/12/17 14:59:59", 24, 0, 4, 102601, 0, 4);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("2020/04/30 12:00:00", 1.81, 24013, 12, 10040, "疲れた…\nけど、次こそは\n守り抜くよ…", "リン", "2030/12/17 14:59:59", 24, 0, 1, 102601, 0, 4);
